import{_ as t,o,c as a,a2 as i}from"./chunks/framework.DXa1R37q.js";const m=JSON.parse('{"title":"Customize lifecycle prompts","description":"","frontmatter":{},"headers":[],"relativePath":"sdlc/customization.md","filePath":"sdlc/customization.md","lastUpdated":1793135521000}'),n={name:"sdlc/customization.md"};function d(c,e,s,r,p,l){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="customize-lifecycle-prompts" tabindex="-1">Customize lifecycle prompts <a class="header-anchor" href="#customize-lifecycle-prompts" aria-label="Permalink to &quot;Customize lifecycle prompts&quot;">​</a></h1><p>Use a project addition when a repository needs extra requirements in one lifecycle command. Use a complete override only when the command structure itself must change.</p><h2 id="add-project-instructions" tabindex="-1">Add project instructions <a class="header-anchor" href="#add-project-instructions" aria-label="Permalink to &quot;Add project instructions&quot;">​</a></h2><p>Create one plain Markdown file under <code>.neottia/templates/sdlc/</code>:</p><table tabindex="0"><thead><tr><th>Command</th><th>File</th></tr></thead><tbody><tr><td>Plan</td><td><code>plan.append.md</code></td></tr><tr><td>Build</td><td><code>build.append.md</code></td></tr><tr><td>Verify</td><td><code>verify.append.md</code></td></tr><tr><td>Release</td><td><code>release.append.md</code></td></tr><tr><td>Continue</td><td><code>continue.append.md</code></td></tr><tr><td>Refresh</td><td><code>refresh.append.md</code></td></tr><tr><td>Adopt</td><td><code>adopt.append.md</code></td></tr></tbody></table><p>For example, <code>.neottia/templates/sdlc/verify.append.md</code> can contain:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Run the project UI checks at the supported viewport sizes.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Attach screenshots for user-visible changes.</span></span></code></pre></div><p>Neottia appends the file under <code>## Project instructions</code> in the matching generated command. It does not add the text to other commands.</p><p>Addition files are plain Markdown. Neottia does not evaluate Twig expressions in them. This text remains literal:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Do not expand {{ instructions.issues }}.</span></span></code></pre></div><p>Project additions do not remove, replace, or reorder canonical text. The generated section ends with a fixed statement that canonical approvals, stop conditions, provider instructions, role instructions, lifecycle transitions, and permission boundaries still apply.</p><p>Run <code>neottia apply --project .</code> after adding or changing a file. Restart the host when package configuration changed. Reloading the host is sufficient when only prompt files changed and the host supports prompt reloads.</p><p>Track project additions in Git. The loader rejects unknown filenames, linked files, invalid text, empty content, and content above the published fragment byte limit.</p><h2 id="replace-a-complete-command" tabindex="-1">Replace a complete command <a class="header-anchor" href="#replace-a-complete-command" aria-label="Permalink to &quot;Replace a complete command&quot;">​</a></h2><p>A complete project override uses <code>.neottia/templates/sdlc/&lt;command&gt;.md.twig</code>. The accepted command names are <code>plan</code>, <code>build</code>, <code>verify</code>, <code>release</code>, <code>continue</code>, <code>refresh</code>, and <code>adopt</code>.</p><p>Complete overrides use the shared Twig layout and can change lifecycle policy. The compiler checks template structure and required capability and role fragments, but it cannot prove that replacement prose preserves the intended workflow. Review a complete override before installation.</p><p>Template precedence is:</p><ol><li>packaged files;</li><li>explicit installed-package layers;</li><li>a global override;</li><li>a project override.</li></ol><p>Global roots accept complete command and protocol overrides. Append-only instruction files are project-scoped.</p><p>The Twig context exposes:</p><ul><li><code>command</code>, with the command ID, transitions, approvals, stop conditions, roles, and enforcement mode;</li><li><code>instructions</code>, with selected capability instruction packs;</li><li><code>roles</code>, with the ordered role instruction entries.</li></ul><p>The shared layout has one block for each capability instruction slot. The compiler rejects duplicate instruction fragments, missing role fragments, dynamic template dependencies, recursive inheritance, unbounded loops, and nondeterministic functions.</p><h2 id="replace-the-operating-protocol" tabindex="-1">Replace the operating protocol <a class="header-anchor" href="#replace-the-operating-protocol" aria-label="Permalink to &quot;Replace the operating protocol&quot;">​</a></h2><p>The operating protocol is a separate plain Markdown template at <code>.neottia/templates/sdlc/protocol.md</code>. It defines shared checkpoint, evidence, approval, and handback procedures.</p><p>Read <a href="/projects/neottia/sdlc/protocol">the operating protocol reference</a> before replacing it. A protocol replacement must preserve the documented checkpoint and permission invariants.</p>`,25)])])}const u=t(n,[["render",d]]);export{m as __pageData,u as default};
